{
  "concepts": [
    {
      "conditions": [],
      "definition": "The subject's application-neutral traversal-occurrence profile: record, relation, identity, causal, effect-boundary, frontier and refusal laws. Adoption or copying transfers no authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1443,
          "quote": "This profile owns only the application-neutral record, relation, identity,\ncausal, effect-boundary, frontier and refusal laws above.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FAuthority%20and%20adoption",
          "start_line": 1438
        }
      ],
      "key": "occurrence_profile",
      "label": "Traversal-occurrence profile"
    },
    {
      "conditions": [],
      "definition": "Complete specialization of RefDomain_Sigma_occurrence(record_kind, qualified_field). O:S restricts O to sort S; AnyLocal is exactly O union E union C union L union X union V union T union J; Sigma:K denotes one exact member of a named closed signature population; empty cells permit no target of that class. B_model means the same M_occ,b and record basis; B_profile exact TraversalOccurrenceProfileBasis resolution; B_calculus exact imported AxiomaticCalculusBasis resolution; B_adopted the exact Product-adoption relation named for the external kind. Sigma:ReferenceDomain, Sigma:ExternalTargetKind and Sigma:BasisRelation belong to this profile's signature.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 267,
          "quote": "The basis codes are exact relations, not labels (P3):",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 250
        }
      ],
      "key": "reference_domain",
      "label": "Finite reference domains and basis relations"
    },
    {
      "conditions": [],
      "definition": "ProfileRecordRef is the closed same-model union of profile semantic-object records O and inherited E, C, L, X, V, T and J; it adds no ninth record kind.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 586,
          "quote": "`ProfileRecordRef` is the closed union of the profile semantic-object\nrecords in `O` and the exact inherited `E`, `C`, `L`, `X`, `V`, `T` and `J`\npopulations in the same model; it introduces no ninth record kind.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20relation%20families",
          "start_line": 582
        }
      ],
      "key": "profile_record",
      "label": "ProfileRecordRef"
    },
    {
      "conditions": [],
      "definition": "Model-validation subject carrying exact model identity and profile-basis reference.",
