      "label": "OccurrenceModelSubject"
    },
    {
      "conditions": [],
      "definition": "An exact pre-existing application identity whose traversal and functor-kind fields equal the occurrence's.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1109,
          "quote": "`application identity` is the exact pre-existing `TraversalApplication`\nidentity, whose traversal and functor-kind fields equal the occurrence's.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FOccurrence%20identity",
          "start_line": 1108
        }
      ],
      "key": "traversal_application",
