      "exceptions": [],
      "grounding": [
        {
          "end_line": 1293,
          "quote": "s_n = EffectSubject(o_n, b_W, q_n, inv_n, op_n, g_n, territory_n, invalidation_n)\nj_ready = judge_effect_readiness(s_n)",
