      "grounding": [
        {
          "end_line": 591,
          "quote": "Each relation is an exact `TypedRelation`. Its qualifiers close direction,\ncardinality, basis, preservation, refusal and invalidation semantics; the\ntable is no permission to omit inherited relation fields.",
