      "conditions": [],
      "definition": "Inherited transformation T has explicit external deltas D_ext={external_preserved, external_introduced, external_removed}, witness resolutions W_ext={external_resolution, domain_resolution, codomain_resolution}, and exact coordinate fields Q_ext={external_identity, reference_domain, external_target_kind, resolved_target_identity, basis_relation, resolution_basis, evidence_identity}. These are distinct from local deltas.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 439,
          "quote": "The external-resolution coordinates of the inherited transformation are\nclosed by this finite expansion and are not hidden inside the three\nlocal-delta rows above (P3, P4b):",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 414
        }
      ],
      "key": "external_resolution",
      "label": "Transformation external-resolution coordinates"
    },
    {
      "conditions": [],
      "definition": "Closed source populations: constraints={identity_dependency_acyclic, occurrence_causation_acyclic, event_causation_acyclic, occurrence_seed_complete, relation_claim_admissible, semantic_cut_complete, pre_effect_current, operation_grant_contains_effect, event_scope_compatible, frontier_complete, transition_subject_complete}; judgments={model_validation, occurrence_admission, event_admission, claim_admission, semantic_cut_admission, effect_readiness, transition_evaluation, frontier_projection}; residuals={unobserved_subject_state, partial_effect, unresolved_cause, unresolved_scope, competing_lineage, stale_frontier, stale_currentness, unobserved_external_mutation}; stops={hold, gap, refusal, invalid_basis, out_of_scope, partial_effect}. Predicate, judgment-decision, stop and effect-disposition result domains remain distinct.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 775,
          "quote": "The core constraint kinds are (P3, P5):",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20constraint%2C%20judgment%2C%20residual%20and%20stop%20kinds",
          "start_line": 724
        }
      ],
      "key": "occurrence_result_domains",
      "label": "Closed kinds and result refinements"
    },
    {
      "conditions": [],
      "definition": "W is the external carrier of mutable reality; observations, evidence, results, checkpoints, events, projections, caches and model content may describe W but do not replace it.",
      "exceptions": [],
      "grounding": [
        {
